diff --git a/tmp/test_split.py b/tmp/test_split.py
new file mode 100644
index 000000000..5819279e9
--- /dev/null
+++ b/tmp/test_split.py
@@ -0,0 +1,97 @@
+import string
+from vllm.reasoning.minimax_m3_reasoning_parser import MiniMaxM3ReasoningParser
+
+class SplitTok:
+    """Tokenizer that does NOT treat markers as single tokens -> char split."""
+    def __init__(self):
+        self.t2i={}; self.i2t={}
+        for c in string.printable: self._add(c)
+        for c in "<>:/mmthink": self._add(c)
+    def _add(self,t):
+        if t not in self.t2i:
+            i=len(self.t2i)+1; self.t2i[t]=i; self.i2t[i]=t
+        return self.t2i[t]
+    def get_vocab(self): return dict(self.t2i)
+    def encode(self,text,add_special_tokens=True,**kw): return [self._add(ch) for ch in text]
+    def decode(self,ids,skip_special_tokens=False):
+        if isinstance(ids,int): ids=[ids]
+        return "".join(self.i2t[i] for i in ids)
+
+def mk(kw=None):
+    t=SplitTok()
+    return MiniMaxM3ReasoningParser(t,chat_template_kwargs=kw), t
+
+def run(p,t,chunks):
+    pt=""; pids=[]; r=[]; c=[]; es=[]
+    for ch in chunks:
+        dids=t.encode(ch,add_special_tokens=False)
+        ct=pt+ch; cids=pids+dids
+        d=p.extract_reasoning_streaming(pt,ct,ch,pids,cids,dids)
+        es.append(p.is_reasoning_end_streaming(cids,dids))
+        if d:
+            if d.reasoning is not None: r.append(d.reasoning)
+            if d.content is not None: c.append(d.content)
+        pt=ct; pids=cids
+    return ("".join(r) or None, "".join(c) or None, es)
+
+# 1. token id helpers with char-split markers (default)
+p,t=mk()
+out=t.encode("<mm:think>abc</mm:think>def",add_special_tokens=False)
+openr=t.encode("<mm:think>abc",add_special_tokens=False)
+plain=t.encode("plain",add_special_tokens=False)
+assert p.is_reasoning_end(out), "is_end out"
+assert not p.is_reasoning_end(openr), "is_end open"
+assert not p.is_reasoning_end(plain), "is_end plain"
+assert t.decode(p.extract_content_ids(out))=="def", t.decode(p.extract_content_ids(out))
+assert p.extract_content_ids(openr)==[], "content open"
+assert p.extract_content_ids(plain)==plain, "content plain"
+assert p.count_reasoning_tokens(out)==3, p.count_reasoning_tokens(out)
+print("split default token helpers OK")
+
+# 2. enabled
+p,t=mk({"thinking_mode":"enabled"})
+out=t.encode("abc</mm:think>def",add_special_tokens=False)
+openr=t.encode("abc",add_special_tokens=False)
+assert p.is_reasoning_end(out)
+assert not p.is_reasoning_end(openr)
+assert t.decode(p.extract_content_ids(out))=="def"
+assert p.extract_content_ids(openr)==[]
+assert p.count_reasoning_tokens(out)==3
+assert p.count_reasoning_tokens(openr)==3
+print("split enabled token helpers OK")
+
+# 3. streaming split end marker default (leading closer split)
+p,t=mk()
+r,c,es=run(p,t,["</mm:th","ink>","answer"])
+assert (r,c)==(None,"answer"), (r,c)
+assert es==[False,True,True], es
+print("split leading closer streaming OK", es)
+
+# 4. streaming split end marker enabled
+p,t=mk({"thinking_mode":"enabled"})
+r,c,es=run(p,t,["plan","</mm:th","ink>","answer"])
+assert (r,c)==("plan","answer"), (r,c)
+assert es==[False,False,True,True], es
+print("split enabled streaming OK", es)
+
+# 5. split start+content+end in one chunk each partial (default)
+p,t=mk()
+r,c,es=run(p,t,["<mm:","think>","pl","an","</mm:","think>","ans"])
+assert (r,c)==("plan","ans"), (r,c)
+print("split all markers streaming OK", es)
+
+# 6. delta with split end marker followed by content -> extract_content_ids
+p,t=mk()
+delta="</mm:think>answer"
+dids=t.encode(delta,add_special_tokens=False)
+cids=p.extract_content_ids(dids)
+assert t.decode(cids)=="answer", t.decode(cids)
+print("extract_content_ids delta split-end OK")
+
+# 7. enabled: reasoning content + set end on completion, split end
+p,t=mk({"thinking_mode":"enabled"})
+r,c,es=run(p,t,["think","ing</mm",":think>","final"])
+assert (r,c)==("thinking","final"), (r,c)
+assert es==[False,False,True,True], es
+print("enabled split-end reasoning attribution OK", es)
+print("ALL SPLIT TESTS PASSED")
