index 000000000..546c3277b
--- /dev/null
+++ b/usr/local/lib/python3.11/site-packages/tblib/__init__.py
@@ -0,0 +1,257 @@
+import re
+import sys
+
+__version__ = '3.2.2'
+__all__ = 'Code', 'Frame', 'Traceback', 'TracebackParseError'
+
+FRAME_RE = re.compile(r'^\s*File "(?P<co_filename>.+)", line (?P<tb_lineno>\d+)(, in (?P<co_name>.+))?$')
+
+
+class _AttrDict(dict):
+    __slots__ = ()
+
+    def __getattr__(self, name):
+        try:
+            return self[name]
+        except KeyError:
+            raise AttributeError(name) from None
+
+
+# noinspection PyPep8Naming
+class __traceback_maker(Exception):
+    pass
+
+
+class TracebackParseError(Exception):
+    pass
+
+
+class Code:
+    """
+    Class that replicates just enough of the builtin Code object to enable serialization and traceback rendering.
+    """
+
+    co_code = None
+
+    def __init__(self, code):
+        self.co_filename = code.co_filename
+        self.co_name = code.co_name
+        self.co_argcount = 0
+        self.co_kwonlyargcount = 0
+        self.co_varnames = ()
+        self.co_nlocals = 0
+        self.co_stacksize = 0
+        self.co_flags = 64
+        self.co_firstlineno = 0
+
+
+class Frame:
+    """
+    Class that replicates just enough of the builtin Frame object to enable serialization and traceback rendering.
+
+    Args:
+
+        get_locals (callable): A function that take a frame argument and returns a dict.
+
+            See :class:`Traceback` class for example.
+    """
+
+    def __init__(self, frame, *, get_locals=None):
+        self.f_locals = {} if get_locals is None else get_locals(frame)
+        self.f_globals = {k: v for k, v in frame.f_globals.items() if k in ('__file__', '__name__')}
+        self.f_code = Code(frame.f_code)
+        self.f_lineno = frame.f_lineno
+
+    def clear(self):
+        """
+        For compatibility with PyPy 3.5;
+        clear() was added to frame in Python 3.4
+        and is called by traceback.clear_frames(), which
+        in turn is called by unittest.TestCase.assertRaises
+        """
+
+
+class Traceback:
+    """
+    Class that wraps builtin Traceback objects.
+
+    Args:
+        get_locals (callable): A function that take a frame argument and returns a dict.
+
+            Ideally you will only return exactly what you need, and only with simple types that can be json serializable.
+
+            Example:
+
+            .. code:: python
+
+                def get_locals(frame):
+                    if frame.f_locals.get("__tracebackhide__"):
+                        return {"__tracebackhide__": True}
+                    else:
+                        return {}
+    """
+
+    tb_next = None
+
+    def __init__(self, tb, *, get_locals=None):
+        self.tb_frame = Frame(tb.tb_frame, get_locals=get_locals)
+        self.tb_lineno = int(tb.tb_lineno)
+
+        # Build in place to avoid exceeding the recursion limit
+        tb = tb.tb_next
+        prev_traceback = self
+        cls = type(self)
+        while tb is not None:
+            traceback = object.__new__(cls)
+            traceback.tb_frame = Frame(tb.tb_frame, get_locals=get_locals)
+            traceback.tb_lineno = int(tb.tb_lineno)
+            prev_traceback.tb_next = traceback
+            prev_traceback = traceback
+            tb = tb.tb_next
+
+    def as_traceback(self):
+        """
+        Convert to a builtin Traceback object that is usable for raising or rendering a stacktrace.
+        """
+        current = self
+        top_tb = None
+        tb = None
+        stub = compile(
+            'raise __traceback_maker',
+            '<string>',
+            'exec',
+        )
+        while current:
+            f_code = current.tb_frame.f_code
+            code = stub.replace(
+                co_firstlineno=current.tb_lineno,
+                co_argcount=0,
+                co_filename=f_code.co_filename,
+                co_name=f_code.co_name,
+                co_freevars=(),
+                co_cellvars=(),
+            )
+
+            # noinspection PyBroadException
+            try:
+                exec(code, dict(current.tb_frame.f_globals), dict(current.tb_frame.f_locals))  # noqa: S102
+            except Exception:
+                next_tb = sys.exc_info()[2].tb_next
+                if top_tb is None:
+                    top_tb = next_tb
+                if tb is not None:
+                    tb.tb_next = next_tb
+                tb = next_tb
+                del next_tb
+
+            current = current.tb_next
+        try:
+            return top_tb
+        finally:
+            del top_tb
+            del tb
+
+    to_traceback = as_traceback
+
+    def as_dict(self):
+        """
+        Converts to a dictionary representation. You can serialize the result to JSON as it only has
+        builtin objects like dicts, lists, ints or strings.
+        """
+        if self.tb_next is None:
+            tb_next = None
+        else:
+            tb_next = self.tb_next.as_dict()
+
+        code = {
+            'co_filename': self.tb_frame.f_code.co_filename,
+            'co_name': self.tb_frame.f_code.co_name,
+        }
+        frame = {
+            'f_globals': self.tb_frame.f_globals,
+            'f_locals': self.tb_frame.f_locals,
+            'f_code': code,
+            'f_lineno': self.tb_frame.f_lineno,
+        }
+        return {
+            'tb_frame': frame,
+            'tb_lineno': self.tb_lineno,
+            'tb_next': tb_next,
+        }
+
+    to_dict = as_dict
+
+    @classmethod
+    def from_dict(cls, dct):
+        """
+        Creates an instance from a dictionary with the same structure as ``.as_dict()`` returns.
+        """
+        if dct['tb_next']:
+            tb_next = cls.from_dict(dct['tb_next'])
+        else:
+            tb_next = None
+
+        code = _AttrDict(
+            co_filename=dct['tb_frame']['f_code']['co_filename'],
+            co_name=dct['tb_frame']['f_code']['co_name'],
+        )
+        frame = _AttrDict(
+            f_globals=dct['tb_frame']['f_globals'],
+            f_locals=dct['tb_frame'].get('f_locals', {}),
+            f_code=code,
+            f_lineno=dct['tb_frame']['f_lineno'],
+        )
+        tb = _AttrDict(
+            tb_frame=frame,
+            tb_lineno=dct['tb_lineno'],
+            tb_next=tb_next,
+        )
+        return cls(tb, get_locals=get_all_locals)
+
+    @classmethod
+    def from_string(cls, string, strict=True):
+        """
+        Creates an instance by parsing a stacktrace. Strict means that parsing stops when lines are not indented by at least two spaces
+        anymore.
+        """
+        frames = []
+        header = strict
+
+        for line in string.splitlines():
+            line = line.rstrip()
+            if header:
+                if line == 'Traceback (most recent call last):':
+                    header = False
+                continue
+            frame_match = FRAME_RE.match(line)
+            if frame_match:
+                frames.append(frame_match.groupdict())
+            elif line.startswith('  '):
+                pass
+            elif strict:
+                break  # traceback ended
+
+        if frames:
+            previous = None
+            for frame in reversed(frames):
+                previous = _AttrDict(
+                    frame,
+                    tb_frame=_AttrDict(
+                        frame,
+                        f_globals=_AttrDict(
+                            __file__=frame['co_filename'],
+                            __name__='?',
+                        ),
+                        f_locals={},
+                        f_code=_AttrDict(frame),
+                        f_lineno=int(frame['tb_lineno']),
+                    ),
+                    tb_next=previous,
+                )
+            return cls(previous)
+        else:
+            raise TracebackParseError(f'Could not find any frames in {string!r}.')
+
+
+def get_all_locals(frame):
+    return dict(frame.f_locals)
diff --git a/usr/local/lib/python3.11/site-packages/tblib/decorators.py b/usr/local/lib/python3.11/site-packages/tblib/decorators.py
new file mode 100644
index 000000000..a1ace4533
--- /dev/null
+++ b/usr/local/lib/python3.11/site-packages/tblib/decorators.py
@@ -0,0 +1,57 @@
+import sys
+from functools import wraps
+
+from . import Traceback
+
+
+def reraise(tp, value, tb=None):
+    try:
+        if value is None:
+            value = tp()
+        if value.__traceback__ is not tb:
+            raise value.with_traceback(tb)
+        raise value
+    finally:
+        value = None
+        tb = None
+
+
+class Error:
+    def __init__(self, exc_type, exc_value, traceback):
+        self.exc_type = exc_type
+        self.exc_value = exc_value
+        self.__traceback = Traceback(traceback)
+
+    @property
+    def traceback(self):
+        return self.__traceback.as_traceback()
+
+    def reraise(self):
+        reraise(self.exc_type, self.exc_value, self.traceback)
+
+
+def return_error(func, exc_type=Exception):
+    @wraps(func)
+    def return_exceptions_wrapper(*args, **kwargs):
+        try:
+            return func(*args, **kwargs)
+        except exc_type:
+            return Error(*sys.exc_info())
+
+    return return_exceptions_wrapper
+
+
+returns_error = return_errors = returns_errors = return_error  # cause I make too many typos
+
+
+@return_error
+def apply_with_return_error(args):
+    """
+    args is a tuple where the first argument is a callable.
+
+    eg::
+
+        apply_with_return_error((func, 1, 2, 3)) - this will call func(1, 2, 3)
+
+    """
+    return args[0](*args[1:])
diff --git a/usr/local/lib/python3.11/site-packages/tblib/pickling_support.py b/usr/local/lib/python3.11/site-packages/tblib/pickling_support.py
new file mode 100644
index 000000000..2f57449df
--- /dev/null
+++ b/usr/local/lib/python3.11/site-packages/tblib/pickling_support.py
@@ -0,0 +1,178 @@
+import copyreg
+import sys
+from functools import partial
+from types import TracebackType
+
+from . import Frame
+from . import Traceback
+
+if sys.version_info < (3, 11):
+    ExceptionGroup = None
+
+
+def unpickle_traceback(tb_frame, tb_lineno, tb_next):
+    ret = object.__new__(Traceback)
+    ret.tb_frame = tb_frame
+    ret.tb_lineno = tb_lineno
+    ret.tb_next = tb_next
+    return ret.as_traceback()
+
+
+def pickle_traceback(tb, *, get_locals=None):
+    return unpickle_traceback, (
+        Frame(tb.tb_frame, get_locals=get_locals),
+        tb.tb_lineno,
+        tb.tb_next and Traceback(tb.tb_next, get_locals=get_locals),
+    )
+
+
+def unpickle_exception_with_attrs(func, attrs, cause, tb, context, suppress_context, notes, args=()):
+    inst = func.__new__(func, *args)
+    for key, value in attrs.items():
+        setattr(inst, key, value)
+    inst.__cause__ = cause
+    inst.__traceback__ = tb
+    inst.__context__ = context
+    inst.__suppress_context__ = suppress_context
+    if notes is not None:
+        inst.__notes__ = notes
+    return inst
+
+
+# Note: Older versions of tblib will generate pickle archives that call unpickle_exception() with
+# fewer arguments. We assign default values to some of the arguments to support this.
+def unpickle_exception(func, args, cause, tb, context=None, suppress_context=False, notes=None):
+    inst = func(*args)
+    inst.__cause__ = cause
+    inst.__traceback__ = tb
+    inst.__context__ = context
+    inst.__suppress_context__ = suppress_context
+    if notes is not None:
+        inst.__notes__ = notes
+    return inst
+
+
+def pickle_exception(
+    obj, builtin_reducers=(OSError.__reduce__, BaseException.__reduce__), builtin_inits=(OSError.__init__, BaseException.__init__)
+):
+    reduced_value = obj.__reduce__()
+    if isinstance(reduced_value, str):
+        raise TypeError('Did not expect {repr(obj)}.__reduce__() to return a string!')
+
+    func = type(obj)
+    # Detect busted objects: they have a custom __init__ but no __reduce__.
+    # This also means the resulting exceptions may be a bit "dulled" down - the args from __reduce__ are discarded.
+    if func.__reduce__ in builtin_reducers and func.__init__ not in builtin_inits:
+        _, args, *optionals = reduced_value
+        attrs = {
+            '__dict__': obj.__dict__,
+            'args': obj.args,
+        }
+        args = ()
+        if isinstance(obj, OSError):
+            # Only set OSError-specific attributes if they are not None
+            # Setting them to None explicitly breaks the string representation
+            if obj.errno is not None:
+                attrs['errno'] = obj.errno
+            if obj.strerror is not None:
+                attrs['strerror'] = obj.strerror
+            if (winerror := getattr(obj, 'winerror', None)) is not None:
+                attrs['winerror'] = winerror
+            if obj.filename is not None:
+                attrs['filename'] = obj.filename
+            if obj.filename2 is not None:
+                attrs['filename2'] = obj.filename2
+        if ExceptionGroup is not None and isinstance(obj, ExceptionGroup):
+            args = (obj.message, obj.exceptions)
+
+        return (
+            unpickle_exception_with_attrs,
+            (
+                func,
+                attrs,
+                obj.__cause__,
+                obj.__traceback__,
+                obj.__context__,
+                obj.__suppress_context__,
+                # __notes__ doesn't exist prior to Python 3.11; and even on Python 3.11 it may be absent
+                getattr(obj, '__notes__', None),
+                args,
+            ),
+            *optionals,
+        )
+    else:
+        func, args, *optionals = reduced_value
+
+        return (
+            unpickle_exception,
+            (
+                func,
+                args,
+                obj.__cause__,
+                obj.__traceback__,
+                obj.__context__,
+                obj.__suppress_context__,
+                # __notes__ doesn't exist prior to Python 3.11; and even on Python 3.11 it may be absent
+                getattr(obj, '__notes__', None),
+            ),
+            *optionals,
+        )
+
+
+def _get_subclasses(cls):
+    # Depth-first traversal of all direct and indirect subclasses of cls
+    to_visit = [cls]
+    while to_visit:
+        this = to_visit.pop()
+        yield this
+        to_visit += list(this.__subclasses__())
+
+
+def install(*exc_classes_or_instances, get_locals=None):
+    """
+    Args:
+
+        get_locals (callable): A function that take a frame argument and returns a dict. See :class:`tblib.Traceback` class for example.
+    """
+    copyreg.pickle(TracebackType, partial(pickle_traceback, get_locals=get_locals))
+
+    if not exc_classes_or_instances:
+        for exception_cls in _get_subclasses(BaseException):
+            copyreg.pickle(exception_cls, pickle_exception)
+        return
+
+    for exc in exc_classes_or_instances:
+        if isinstance(exc, BaseException):
+            _install_for_instance(exc, set())
+        elif isinstance(exc, type) and issubclass(exc, BaseException):
+            copyreg.pickle(exc, pickle_exception)
+            # Allow using @install as a decorator for Exception classes
+            if len(exc_classes_or_instances) == 1:
+                return exc
+        else:
+            raise TypeError(f'Expected subclasses or instances of BaseException, got {type(exc)}')
+
+
+def _install_for_instance(exc, seen):
+    assert isinstance(exc, BaseException)
+
+    # Prevent infinite recursion if we somehow get a self-referential exception. (Self-referential
+    # exceptions should never normally happen, but if it did somehow happen, we want to pickle the
+    # exception faithfully so the developer can troubleshoot why it happened.)
+    if id(exc) in seen:
+        return
+    seen.add(id(exc))
+
+    copyreg.pickle(type(exc), pickle_exception)
+
+    if exc.__cause__ is not None:
+        _install_for_instance(exc.__cause__, seen)
+    if exc.__context__ is not None:
+        _install_for_instance(exc.__context__, seen)
+
+    # This case is meant to cover BaseExceptionGroup on Python 3.11 as well as backports like the
